using System.Collections.Generic;
using Comindware.Platform.Api.Data;
using Comindware.TeamNetwork.Api.Data.UserCommands;

class Script
{
    public static UserCommandResult Main(UserCommandContext userCommandContext, Comindware.Entities entities)
    {
        var refr = new PredefinedDataNavigationReference();
        // refr.ObjectId = "cmw.temp.123"; // Temporary template record
        refr.ObjectTypeId = "oa.104"; // Template record to reference
        refr.TargetType = NavigationItemType.Form; // Link type reference
        refr.TargetId = "form.238"; // Form reference
        foreach (var objectId in userCommandContext.ObjectIds)
        {
            var data = new Dictionary<string, object>
            {
                { "Space_calc", objectId }
            };
            refr.PredefinedData = data; // Data pre-fill
            var link = Api.Base.EncryptedNavigationReferenceService.Generate(refr);
            var data2 = new Dictionary<string, object>
            {
                { "ServiceRequestQRlinktext_calc", link } // Attribute to save document into
            };
           Api.TeamNetwork.ObjectService.EditWithAlias("Spaces_calc", objectId, data2); // Replace attribute values by key for template record
        }
        var result = new UserCommandResult
        {
            Success = true,
            Commited = true,
            ResultType = UserCommandResultType.Undefined
        };
        return result;
    }
}
